import numpy as np

def feature(pos, targets, values, rates, battery, drain, charge_rate, charger, time, time_left, history):
    """Value each candidate item would still have on arrival (values - rates*distance), zero if unreachable in time, normalised by the max current value."""
    d = np.linalg.norm(targets - pos[None, :], axis=1)
    net = np.where(d <= time_left, np.maximum(values - rates * d, 0.0), 0.0)
    return net / (np.max(values) + 1e-9)

import numpy as np

def feature(pos, targets, values, rates, battery, drain, charge_rate, charger, time, time_left, history):
    """Value of each candidate item divided by its distance from the drone (0 for the charger), normalised by the max."""
    d = np.linalg.norm(targets - pos[None, :], axis=1)
    ratio = np.where(values > 0, values / (d + 1e-6), 0.0)
    return ratio / (np.max(ratio) + 1e-9)

