import numpy as np

def feature(pos, targets, values, rates, battery, drain, charge_rate, charger, time, time_left, history):
    """Recency-weighted Gaussian arrival density around each candidate, normalised by its max."""
    k = targets.shape[0]
    if history.shape[0] == 0:
        return np.zeros(k)
    h = history[:, :2]
    tau = np.exp(-(time - history[:, 2]) / 20.0)
    d2 = ((targets[:, None, :] - h[None, :, :]) ** 2).sum(axis=2)
    kern = np.exp(-d2 / (2.0 * 0.15 ** 2))
    S = (kern * tau[None, :]).sum(axis=1) / (tau.sum() + 1e-9)
    return S / (S.max() + 1e-9)

import numpy as np

def feature(pos, targets, values, rates, battery, drain, charge_rate, charger, time, time_left, history):
    """Burst-vs-lull flux ratio f times a relative trip-length term (0.5 - d/max_d) for items, 0 for the charger."""
    W = 8.0
    is_item = values > 0
    d = np.linalg.norm(targets - pos, axis=1)
    trip = np.maximum(d, 1e-3)
    Vs = np.where(is_item, np.maximum(values - rates * d, 0.0), 0.0)
    if np.any(is_item):
        service = float(np.mean(Vs[is_item] / trip[is_item]))
    else:
        service = 0.0
    if history.shape[0] > 0:
        recent = history[history[:, 2] >= time - W, 3]
        flux = float(np.sum(recent)) / W
    else:
        flux = 0.0
    f = flux / (flux + service + 1e-9)
    if np.any(is_item):
        mx_t = max(float(np.max(d[is_item])), 1e-6)
    else:
        mx_t = 1e-6
    rel = 0.5 - d / mx_t
    return np.where(is_item, f * rel, 0.0)
